import { useId, useState, type ReactNode } from "react";
import { ChevronDown } from "lucide-react";
import { cn } from "@/lib/cn";

// native selects only (no Radix Select, no custom list).
// Options are data. the app's time list is not specified: src/fixtures/schedule.ts holds fixtures.
// A value is always selected; there is no placeholder, no disabled state, no confirm step.

export type SelectOption = { value: string; label: string };

export type SelectFieldProps = {
  label: string;
  /** Language of the label; uppercase and tracking apply to Latin text only. */
  labelLang?: string;
  options: SelectOption[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  className?: string;
};

const labelClass =
  "font-body text-ui-floor font-label leading-normal text-text-muted latin:uppercase latin:tracking-label [overflow-wrap:anywhere]";

/** One labelled native select with our caret. Use directly for a single field, or via ScheduleField for the pair. */
export function SelectField({ label, labelLang, options, value, defaultValue, onValueChange, className }: SelectFieldProps) {
  const id = useId();
  const [inner, setInner] = useState(defaultValue ?? options[0]?.value);
  const current = value ?? inner;
  if (import.meta.env.DEV && !options.some((o) => o.value === current)) {
    console.warn(`[SelectField] value "${current}" is not one of the options for "${label}".`);
  }
  return (
    <div className={cn("flex w-full min-w-0 flex-col gap-stack-sm", className)}>
      <label htmlFor={id} lang={labelLang} className={labelClass}>
        {label}
      </label>
      <div className="relative w-full">
        <select
          id={id}
          value={current}
          onChange={(e) => {
            setInner(e.target.value);
            onValueChange?.(e.target.value);
          }}
          className={cn(
            "block min-h-control w-full appearance-none rounded-control border-bw-default border-border-strong bg-surface-raised",
            "ps-inset-sm pe-select-end font-body text-ui-reading font-regular leading-normal text-text",
            "focus-visible:outline focus-visible:outline-ring focus-visible:outline-offset-ring focus-visible:outline-focus-ring",
          )}
        >
          {options.map((o) => (
            <option key={o.value} value={o.value}>
              {o.label}
            </option>
          ))}
        </select>
        <ChevronDown aria-hidden="true" className="pointer-events-none absolute end-1 top-1/2 size-icon-sm -translate-y-1/2 text-text" />
      </div>
    </div>
  );
}

export type ScheduleFieldProps = {
  /** Group name, for example "Plan next week on" (provisional).*/
  legend: string;
  /** Description of the group, for example "Next week is planned at this time, or the first time you open the app after it." */
  helper?: ReactNode;
  day: Omit<SelectFieldProps, "className">;
  time: Omit<SelectFieldProps, "className">;
  className?: string;
};

/** Day and time in a group, always stacked at the full width of the group (D-4 ruling). */
export function ScheduleField({ legend, helper, day, time, className }: ScheduleFieldProps) {
  const helperId = useId();
  return (
    <fieldset aria-describedby={helper ? helperId : undefined} className={cn("min-w-0", className)}>
      <legend className="mb-stack-sm p-0 font-body text-ui-reading font-label leading-normal text-text">{legend}</legend>
      <div className="flex flex-col gap-gap-md">
        <SelectField {...day} />
        <SelectField {...time} />
      </div>
      {helper && (
        <div id={helperId} className="mt-stack-sm font-body text-ui-reading font-regular leading-normal text-text-muted">
          {helper}
        </div>
      )}
    </fieldset>
  );
}
